// ECP5-P1 HDMI unit tests (Verilator):
//  1. tmds_enc against an independent C++ implementation of the DVI 1.0 8b/10b algorithm
//     (random and exhaustive data with running disparity), the 4 control tokens, the 16
//     TERC4 codes and the guard bands (HDMI 1.4 tables; q[9:0], bit 0 transmitted first).
//  2. Colour bars + gradient (640x480, VESA 800x525 timing, negative syncs) generated by the
//     testbench -> hdmi_tx (CTS 25000) -> ecp5_tmds_ser (ODDRX1F) -> pad bits ->
//     deserializer (clock lane) -> HDMI sink model. Checks: every frame equal to the
//     generated image, HSYNC low exactly 96 pixels / VSYNC low exactly 2 lines (negative
//     polarity, positions checked by the sink model), 10 bits per symbol on every lane,
//     serial == parallel symbols, many frames without misalignment, audio samples injected
//     at 48 kHz received contiguously, ACR N/CTS, AVI/Audio InfoFrames.
#include "Vhdmi_unit_top.h"
#include "verilated.h"
#include "../m4/hdmi_dec.h"
#include "tmds_deser.h"
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <cmath>

static int pop8(unsigned v) { return __builtin_popcount(v & 0xFF); }
// DVI 1.0 section 3.3.3 (Figure 3-5), written from the specification text
static uint16_t dvi_enc(uint8_t D, int &cnt) {
    int n1d = pop8(D);
    bool x = n1d > 4 || (n1d == 4 && !(D & 1));
    unsigned qm = D & 1;
    for (int i = 1; i < 8; i++) {
        unsigned prev = (qm >> (i - 1)) & 1, di = (D >> i) & 1;
        unsigned b = x ? !(prev ^ di) : (prev ^ di);
        qm |= b << i;
    }
    unsigned qm8 = x ? 0 : 1;
    int n1 = pop8(qm), n0 = 8 - n1;
    uint16_t q;
    if (cnt == 0 || n1 == n0) {
        q = ((qm8 ? 0 : 1) << 9) | (qm8 << 8) | (qm8 ? qm : (~qm & 0xFF));
        cnt += qm8 ? (n1 - n0) : (n0 - n1);
    } else if ((cnt > 0 && n1 > n0) || (cnt < 0 && n0 > n1)) {
        q = (1 << 9) | (qm8 << 8) | (~qm & 0xFF);
        cnt += 2 * (int)qm8 + (n0 - n1);
    } else {
        q = (0 << 9) | (qm8 << 8) | qm;
        cnt += -2 * (int)(!qm8) + (n1 - n0);
    }
    return q;
}
// HDMI 1.4 tables (as q[9:0]; same constants as hdl-util/hdmi, DVI control tokens)
static const uint16_t CTRL[4] = {0x354, 0x0AB, 0x154, 0x2AB};   // 1101010100, 0010101011, 0101010100, 1010101011
static const uint16_t TERC4[16] = {0x29C, 0x263, 0x2E4, 0x2E2, 0x171, 0x11E, 0x18E, 0x13C,
                                   0x2CC, 0x139, 0x19C, 0x2C6, 0x28E, 0x271, 0x163, 0x2C3};

static Vhdmi_unit_top *dut;
static int errors = 0;

int main(int argc, char **argv) {
    int nframes = argc > 1 ? atoi(argv[1]) : 20;
    VerilatedContext *ctx = new VerilatedContext;
    ctx->commandArgs(argc, argv);
    dut = new Vhdmi_unit_top(ctx);
    HdmiDec hd;
    TmdsDeser des;
    SerParCheck spc;

    // ---------------------------------------------------------------- 1. encoder vectors
    // drive tmds_enc alone with clk_pix (clk_x5 idle); output q is registered (1 clock)
    auto pclk = [&]() { dut->clk_pix = 1; dut->eval(); dut->clk_pix = 0; dut->eval(); };
    dut->rst = 1; dut->clk_pix = 0; dut->clk_x5 = 0; dut->eval();
    long enc_checked = 0, enc_bad = 0;
    {
        // control token resets the RTL disparity counter; the model starts at 0 as well
        unsigned s = 12345;
        int cnt = 0;
        std::vector<int> mode_seq;
        dut->e_mode = 0; dut->e_c = 0; pclk();
        for (int i = 0; i < 300000; i++) {
            int mode; uint8_t d = 0; int c = 0, t = 0;
            if (i < 256 * 4) { mode = 1; d = (uint8_t)(i & 255); }                 // exhaustive in 4 passes
            else {
                s = s * 1103515245 + 12345;
                int r = (s >> 16) % 100;
                mode = r < 80 ? 1 : r < 88 ? 0 : r < 94 ? 3 : r < 97 ? 2 : 4;
                d = (uint8_t)(s >> 3); c = (s >> 9) & 3; t = (s >> 12) & 15;
            }
            dut->e_mode = mode; dut->e_d = d; dut->e_c = c; dut->e_t = t;
            pclk();
            uint16_t exp;
            switch (mode) {
                case 1: exp = dvi_enc(d, cnt); break;
                case 0: exp = CTRL[c]; cnt = 0; break;
                case 2: exp = 0x2CC; cnt = 0; break;                  // video guard band, channel 0
                case 3: exp = TERC4[t]; cnt = 0; break;
                default: exp = TERC4[t]; cnt = 0; break;              // data island guard, channel 0
            }
            enc_checked++;
            if (dut->e_q != exp) {
                if (enc_bad < 10) fprintf(stderr, "TMDS enc #%d modo %d d=%02x c=%d t=%x: rtl=%03x esperado=%03x\n",
                                          i, mode, d, c, t, dut->e_q, exp);
                enc_bad++;
            }
        }
        if (enc_bad) errors++;
        printf("1. codificador TMDS: %ld símbolos conferidos com o modelo DVI 1.0 independente "
               "(256 valores x 4 passadas + aleatórios com disparidade, 4 tokens, 16 TERC4, guard bands), %ld errados\n",
               enc_checked, enc_bad);
    }

    // ---------------------------------------------------------------- 2. bars -> serial -> sink
    auto bars = [](int x, int y, uint8_t *rgb) {
        static const uint8_t B[8][3] = {{255,255,255},{255,255,0},{0,255,255},{0,255,0},
                                        {255,0,255},{255,0,0},{0,0,255},{0,0,0}};
        if (y < 320) { memcpy(rgb, B[x / 80], 3); }
        else { rgb[0] = x & 255; rgb[1] = (y * 3) & 255; rgb[2] = (x + y) & 255; }
    };
    std::vector<uint8_t> expf(640 * 480 * 3);
    for (int y = 0; y < 480; y++) for (int x = 0; x < 640; x++) bars(x, y, &expf[(y * 640 + x) * 3]);

    int gx = 0, gy = 0;
    long frames_ok = 0, frames_cmp = 0;
    std::vector<int16_t> sent_l, sent_r;
    long long aacc = 0;
    long hs_low = 0, vs_low = 0, hs_runs = 0, vs_runs = 0, hs_bad = 0, vs_bad = 0;
    int prev_hs = 1, prev_vs = 1;
    dut->rst = 1;
    uint64_t pix = 0, lock_pix = 0;
    const uint64_t max_pix = (uint64_t)(nframes + 2) * 800 * 525;
    // 2 ns grid not needed here: clk_x5 = 5 x clk_pix, rising edges aligned (unit = 4 ns)
    for (uint64_t u = 0; pix < max_pix; u++) {
        bool x5_tog = true, pix_tog = (u % 5 == 0);
        dut->clk_x5 = !dut->clk_x5;
        if (pix_tog) dut->clk_pix = !dut->clk_pix;
        bool pix_rise = pix_tog && dut->clk_pix;
        if (pix_rise) {
            // inputs for the next pixel (setup before this edge is evaluated is not modelled;
            // values change right after the edge, as from a register)
        }
        dut->eval();
        if (pix_rise) {
            pix++;
            if (pix == 20) dut->rst = 0;
            spc.on_parallel(dut->t0, dut->t1, dut->t2);
            // next pixel of the source
            uint8_t rgb[3] = {0, 0, 0};
            bool de = gx < 640 && gy < 480;
            if (de) bars(gx, gy, rgb);
            dut->r = rgb[0]; dut->g = rgb[1]; dut->b = rgb[2]; dut->de = de;
            dut->hs_n = !(gx >= 656 && gx < 752);
            dut->vs_n = !(gy >= 490 && gy < 492);
            if (++gx == 800) { gx = 0; if (++gy == 525) gy = 0; }
            // audio at exactly 48 kHz of the 25 MHz pixel clock
            dut->aud_we = 0;
            aacc += 48000;
            if (aacc >= 25000000) {
                aacc -= 25000000;
                int n = sent_l.size();
                int16_t l = (int16_t)lrint(8000 * sin(2 * M_PI * 1000.0 * n / 48000.0));
                int16_t r = (int16_t)(n * 37);
                dut->aud_we = 1; dut->aud_l = (uint16_t)l; dut->aud_r = (uint16_t)r;
                sent_l.push_back(l); sent_r.push_back(r);
            }
        }
        // the sink starts once the transmitter has aligned its counters to the input syncs
        // (hdmi_tx 'locked', first HSYNC after reset); before that the first line after reset
        // has its blanking at the transmitter's free-running position (documented transient)
        // (the lock flag rises at an HSYNC: start two lines + 200 pixels later, in the active
        // area, so that the sink does not begin inside a sync pulse and see a false edge)
        if (dut->locked && !lock_pix) lock_pix = pix;
        if (x5_tog && lock_pix && pix > lock_pix + 1800) {
            long mis0 = des.misalign, herr0 = hd.errors;
            bool got = des.bit(dut->tmds_q & 1, (dut->tmds_q >> 1) & 1, (dut->tmds_q >> 2) & 1, (dut->tmds_q >> 3) & 1);
            if (getenv("DBG") && des.misalign != mis0) fprintf(stderr, "dbg: desalinhamento no pixel %llu (símbolo %ld)\n", (unsigned long long)pix, des.symbols);
            if (got) {
                spc.on_serial(des.out);
                hd.symbol(des.out[0], des.out[1], des.out[2]);
                if (getenv("DBG") && hd.errors != herr0) fprintf(stderr, "dbg: erro do sink no pixel %llu (símbolo %ld, frames %d)\n", (unsigned long long)pix, des.symbols, hd.frames_done);
                // sync widths/polarity as seen by the sink (hs/vs = 1 when idle)
                if (hd.synced) {
                    if (!hd.hs) hs_low++;
                    if (prev_hs == 0 && hd.hs) { hs_runs++; if (hs_low != 96) hs_bad++; hs_low = 0; }
                    if (!hd.vs) vs_low++;
                    if (prev_vs == 0 && hd.vs) { vs_runs++; if (vs_low != 1600) vs_bad++; vs_low = 0; }
                } else { hs_low = vs_low = 0; }
                prev_hs = hd.hs; prev_vs = hd.vs;
                if (hd.frame_ready) {
                    hd.frame_ready = false;
                    if (hd.frames_done >= 2) {
                        long diff = 0;
                        for (size_t i = 0; i < expf.size(); i += 3)
                            if (memcmp(&expf[i], &hd.last_frame[i], 3)) diff++;
                        frames_cmp++;
                        if (diff) { errors++; fprintf(stderr, "frame %d: %ld pixels diferentes\n", hd.frames_done, diff); }
                        else frames_ok++;
                        if (hd.frames_done == 3) {
                            FILE *f = fopen("ecp5_colorbars.ppm", "wb");
                            if (f) { fprintf(f, "P6\n640 480\n255\n"); fwrite(hd.last_frame.data(), 1, hd.last_frame.size(), f); fclose(f); }
                        }
                    }
                }
            }
        }
    }
    // audio: received samples must be a contiguous run of the sent ones
    long off = -1;
    for (size_t o = 0; o < sent_l.size() && !hd.aud_l.empty(); o++)
        if (sent_l[o] == hd.aud_l[0] && sent_r[o] == hd.aud_r[0]) {
            bool ok = true;
            for (size_t i = 0; i < hd.aud_l.size(); i++)
                if (o + i >= sent_l.size() || sent_l[o + i] != hd.aud_l[i] || sent_r[o + i] != hd.aud_r[i]) { ok = false; break; }
            if (ok) { off = o; break; }
        }
    if (off < 0 || hd.aud_l.size() < 1000) { errors++; fprintf(stderr, "áudio recebido não é uma sequência contínua do enviado\n"); }
    if (hd.errors) { errors++; fprintf(stderr, "sink: %ld erros\n", hd.errors); }
    if (des.misalign || des.bad_clock) { errors++; fprintf(stderr, "desalinhamento %ld, clock %ld\n", des.misalign, des.bad_clock); }
    if (spc.lat < 0 || spc.mismatches) { errors++; fprintf(stderr, "serial x paralelo: lat %d, %ld diferenças\n", spc.lat, spc.mismatches); }
    if (hs_bad || vs_bad || hs_runs < 1000 || vs_runs < 3) { errors++; fprintf(stderr, "sincronismo: hs %ld/%ld errados, vs %ld/%ld errados\n", hs_bad, hs_runs, vs_bad, vs_runs); }
    if (hd.acr_n != 6144 || hd.acr_cts != 25000) { errors++; fprintf(stderr, "ACR %d/%d\n", hd.acr_n, hd.acr_cts); }
    if (hd.avi_vic != 1 || hd.n_aif == 0) { errors++; fprintf(stderr, "InfoFrames AVI VIC %d, Audio IF %ld\n", hd.avi_vic, hd.n_aif); }
    if (dut->aud_overflow) { errors++; fprintf(stderr, "overflow na FIFO de áudio\n"); }
    if (frames_cmp < nframes - 2) { errors++; fprintf(stderr, "poucos frames comparados\n"); }
    printf("2. barras coloridas -> hdmi_tx -> ecp5_tmds_ser -> pinos -> sink: %ld/%ld frames iguais, %ld símbolos (%ld desalinhados, clock lane errada %ld)\n",
           frames_ok, frames_cmp, des.symbols, des.misalign, des.bad_clock);
    printf("   serial x paralelo: latência %d pixels, %ld diferenças em %ld símbolos (ordem dos 10 bits, 3 lanes + clock)\n",
           spc.lat, spc.mismatches, spc.n);
    printf("   HSYNC baixo 96 pixels em %ld/%ld linhas, VSYNC baixo 2 linhas em %ld/%ld frames (polaridade negativa)\n",
           hs_runs - hs_bad, hs_runs, vs_runs - vs_bad, vs_runs);
    printf("   áudio: %zu amostras enviadas a 48 kHz, %zu recebidas em sequência (início no índice %ld), ACR N=%d CTS=%d (%ld pacotes), AVI VIC=%d, Audio IF %ld, erros do sink %ld\n",
           sent_l.size(), hd.aud_l.size(), off, hd.acr_n, hd.acr_cts, hd.n_acr, hd.avi_vic, hd.n_aif, hd.errors);
    printf("HDMI unit: %s\n", errors ? "FALHOU" : "OK");
    delete dut; delete ctx;
    return errors ? 1 : 0;
}
